  const greenFill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FFC6EFCE' }
  };

  const greenFont = {
    bold: true,
    color: { argb: 'FF006100' }
  };

  const newUpdates = {
    425: '070-8064-2908', // (주)비욘디
    430: '051-867-7074',  // (주)진플러스
    498: '051-714-6963',  // (주)티라
    500: '010-4014-5472', // 타이거인공지능
    522: '02-6956-3921',  // (주)엑스타
    526: '051-911-2109',  // (주)태성소프트기술
    531: '070-7642-7000', // (주)빅메이드
    535: '1670-6461',     // 올라운더(주)
    543: '1688-0724',     // (주)뱅크다이어리
    548: '070-4286-5321', // 디케이즈(주)
    560: '010-7444-4894'  // (주)루비엔터테인먼트
  };

  let count = 0;
  for (let r = 2; r <= ws.rowCount; r++) {
    const seq = ws.getRow(r).getCell(1).value;
    if (seq !== null && seq !== undefined && newUpdates[Number(seq)]) {
      const cell = ws.getRow(r).getCell(10);
      cell.value = newUpdates[Number(seq)];
      cell.fill = greenFill;
      cell.font = greenFont;
      count++;
    }
  }

  console.log('Updated rows:', count);

  // Count totals
  let totalFilled = 0;
  let totalGreen = 0;
  for (let r = 2; r <= ws.rowCount; r++) {
    const cell = ws.getRow(r).getCell(10);
    const val = (cell.value || '').toString().trim();
    if (val) totalFilled++;
    if (cell.fill && cell.fill.fgColor && cell.fill.fgColor.argb === 'FFC6EFCE') {
      totalGreen++;
    }
  }

  console.log('Total filled in 심층6차:', totalFilled);
  console.log('Total green in 심층6차:', totalGreen);

  await wb.xlsx.writeFile(f_out6);
