  } catch (err) {
    console.log('심층5차 is currently open in Excel, so 심층6차.xlsx serves as the new latest version.');
  }

  // Update TXT
  const lines = [];
  for (let r = 1; r <= ws.rowCount; r++) {
    const rowVals = [];
    for (let c = 1; c <= ws.columnCount; c++) {
      const v = ws.getRow(r).getCell(c).value;
      rowVals.push(v !== null && v !== undefined ? String(v) : '');
    }
    lines.push(rowVals.join('\t'));
  }
  fs.writeFileSync(f_txt, '\uFEFF' + lines.join('\n'), 'utf-8');
  console.log('Successfully synced TXT file!');

  // Update merged_step2.json
  const jsonPath = 'data/merged_step2.json';
  const data = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
  for (const item of data) {
    if (newUpdates[item.seq]) {
      item.phone = newUpdates[item.seq];
      item.source = '심층2차검증(웹교차검증)';
    }
  }
  fs.writeFileSync(jsonPath, JSON.stringify(data, null, 2), 'utf8');
  console.log('Successfully synced merged_step2.json!');
}

updateWorkbook().catch(console.error);
